    from typing import TypeGuard

    from vegafusion.runtime import ChartState


_VEGAFUSION_IS_V2: Final = (
    Version(_version) >= Version("2.0.0a0")
    if (_version := importlib_version("vegafusion"))
    else False
)


if _VEGAFUSION_IS_V2:
    # VegaFusion v2 supports narwhals-compatible DataFrames
    def supported_by_vf(data: Any) -> TypeGuard[IntoDataFrame]:
        return isinstance(data, DataFrameLike) or isinstance(
            nw.from_native(data, pass_through=True), (nw.DataFrame, nw.LazyFrame)
        )
else:

    def supported_by_vf(data: Any) -> TypeGuard[DataFrameLike]:
        return isinstance(data, DataFrameLike)
